import React, { useRef, useMemo } from 'react';
import { useFrame } from '@react-three/fiber';
import { Float, Text, useScroll, Image, MeshReflectorMaterial, Instance, Instances } from '@react-three/drei';
import * as THREE from 'three';
import AvatarSystem from '../components/AvatarSystem';

// --- HOLOGRAPHIC DATA RINGS ---
const DataRing = ({ radius, speed, color, position, rotationAxis }) => {
  const meshRef = useRef();
  useFrame((state, delta) => {
    if (meshRef.current) {
      if (rotationAxis === 'x') meshRef.current.rotation.x += delta * speed;
      if (rotationAxis === 'y') meshRef.current.rotation.y += delta * speed;
      if (rotationAxis === 'z') meshRef.current.rotation.z += delta * speed;
    }
  });

  return (
    <mesh ref={meshRef} position={position} rotation={[Math.PI/2, 0, 0]}>
      <torusGeometry args={[radius, 1.5, 16, 100]} />
      <meshBasicMaterial color={color} transparent opacity={0.8} blending={THREE.AdditiveBlending} />
    </mesh>
  );
};

// --- PROCEDURAL NEURAL GRID ---
const synapseVertexShader = `
  varying vec2 vUv;
  varying vec3 vWorldPos;
  void main() {
    vUv = uv;
    vec4 worldPos = modelMatrix * instanceMatrix * vec4(position, 1.0);
    vWorldPos = worldPos.xyz;
    gl_Position = projectionMatrix * viewMatrix * worldPos;
  }
`;

const synapseFragmentShader = `
  varying vec3 vWorldPos;
  uniform float uTime;
  void main() {
    // Pulse based on world position and time
    float pulse = sin(vWorldPos.x * 0.01 + uTime * 2.0) * sin(vWorldPos.y * 0.01 + uTime * 3.0) * sin(vWorldPos.z * 0.01 + uTime * 1.5);
    pulse = smoothstep(0.7, 1.0, pulse);
    
    vec3 baseColor = vec3(0.05, 0.1, 0.2);
    vec3 glowColor = vec3(0.0, 0.5, 1.0) * pulse * 5.0;
    
    gl_FragColor = vec4(baseColor + glowColor, 0.8);
  }
`;

const NeuralGrid = ({ visible }) => {
  const gridSize = 10;
  const spacing = 150;
  const count = gridSize * gridSize * gridSize;
  
  const uniforms = useMemo(() => ({ uTime: { value: 0 } }), []);

  useFrame((state) => {
    if (!visible) return;
    uniforms.uTime.value = state.clock.elapsedTime;
  });

  const instances = useMemo(() => {
    const arr = [];
    const offset = (gridSize * spacing) / 2;
    for (let x = 0; x < gridSize; x++) {
      for (let y = 0; y < gridSize; y++) {
        for (let z = 0; z < gridSize; z++) {
          // Leave the center empty for the Cortex
          const distToCenter = Math.sqrt(Math.pow(x - gridSize/2, 2) + Math.pow(y - gridSize/2, 2) + Math.pow(z - gridSize/2, 2));
          if (distToCenter < 3.0) continue;
          
          arr.push({
            position: [x * spacing - offset, y * spacing - offset, z * spacing - offset],
            scale: [1, 1, 1]
          });
        }
      }
    }
    return arr;
  }, [gridSize, spacing]);

  return (
    <group position={[0, 150, -800]}>
      {/* Nodes */}
      <Instances range={instances.length} material={new THREE.ShaderMaterial({
        vertexShader: synapseVertexShader,
        fragmentShader: synapseFragmentShader,
        uniforms: uniforms,
        transparent: true,
        blending: THREE.AdditiveBlending
      })}>
        <sphereGeometry args={[4, 16, 16]} />
        {instances.map((props, i) => <Instance key={i} {...props} />)}
      </Instances>
      
      {/* Connective Lines (Faint Grid) */}
      <mesh>
        <boxGeometry args={[gridSize * spacing, gridSize * spacing, gridSize * spacing, gridSize-1, gridSize-1, gridSize-1]} />
        <meshBasicMaterial color="#0055ff" wireframe transparent opacity={0.03} blending={THREE.AdditiveBlending} />
      </mesh>
    </group>
  );
};

// --- AI CORTEX ---
const AICortex = ({ position }) => {
  const cortexRef = useRef();
  useFrame((state, delta) => {
    if (cortexRef.current) cortexRef.current.rotation.y += delta * 0.2;
  });

  return (
    <group position={position}>
      {/* Inner Energy Core */}
      <mesh position={[0, 0, 0]}>
        <icosahedronGeometry args={[80, 2]} />
        <meshBasicMaterial color="#ffffff" wireframe />
      </mesh>
      
      {/* Outer Quantum Crystal */}
      <mesh ref={cortexRef}>
        <icosahedronGeometry args={[140, 0]} />
        <meshPhysicalMaterial 
          color="#ffffff"
          transmission={1.0}
          opacity={1}
          metalness={0.0}
          roughness={0.0}
          ior={1.5}
          thickness={50}
          clearcoat={1}
          clearcoatRoughness={0.0}
          dispersion={2.0} // Chromatic dispersion!
          side={THREE.DoubleSide}
        />
      </mesh>
      
      {/* Data Rings */}
      <DataRing radius={200} speed={1.5} color="#00ffff" position={[0,0,0]} rotationAxis="x" />
      <DataRing radius={220} speed={-1.0} color="#00aaff" position={[0,0,0]} rotationAxis="y" />
      <DataRing radius={240} speed={0.8} color="#ffffff" position={[0,0,0]} rotationAxis="z" />
      
      <pointLight intensity={5} color="#0077ff" distance={1000} />
      <pointLight intensity={3} color="#ffffff" distance={500} />
    </group>
  );
};

// --- MAIN COMPONENT ---
const WorldAutopilot = ({ position, rotation, visible }) => {
  const scroll = useScroll();
  const lockRef = useRef({ timer: 0, triggered: false, locked: false });

  useFrame((state, delta) => {
    if (!visible) return;
    const p = scroll.offset;
    const s = lockRef.current;
    
    if (p >= 0.59 && p <= 0.62 && !s.triggered) {
      s.triggered = true;
      s.locked = true;
      s.timer = 0;
      if (scroll.el) {
        scroll.el.style.overflow = 'hidden';
        scroll.el.scrollTop = 0.60 * (scroll.el.scrollHeight - scroll.el.clientHeight);
      }
    }
    
    if (s.locked) {
      s.timer += delta;
      if (s.timer > 2.0) {
        s.locked = false;
        if (scroll.el) scroll.el.style.overflow = 'auto';
      } else {
        if (scroll.el) scroll.el.scrollTop = 0.60 * (scroll.el.scrollHeight - scroll.el.clientHeight);
      }
    }
  });

  return (
    <group visible={visible} position={position} rotation={rotation}>
      <ambientLight intensity={0.5} color="#ffffff" />
      
      <mesh rotation={[0, -Math.PI / 2, 0]}>
        <sphereGeometry args={[4000, 32, 32]} />
        <meshBasicMaterial color="#02040a" side={THREE.BackSide} />
      </mesh>

      <mesh position={[0, -200, 0]} rotation={[-Math.PI / 2, 0, 0]}>
        <planeGeometry args={[5000, 5000]} />
        <MeshReflectorMaterial
          blur={[400, 100]}
          resolution={1024}
          mixBlur={1}
          mixStrength={100}
          roughness={0.02}
          depthScale={1.5}
          minDepthThreshold={0.4}
          maxDepthThreshold={1.4}
          color="#010204"
          metalness={1.0}
        />
      </mesh>

      <AICortex position={[0, 150, -800]} />
      <NeuralGrid visible={visible} />

      {visible && <AvatarSystem position={[0, -180, -400]} scale={2.0} greeting="Welcome to the Autopilot Nexus. Neural grid synchronized." />}

      <group position={[0, 550, -600]}>
        <Float speed={2} rotationIntensity={0.02} floatIntensity={0.2}>
          <Image url="/autopilot_logo.png" position={[0, 120, 0]} scale={[250, 250]} transparent opacity={0.9} />
          <Text font="/fonts/Roboto.woff" fallbackFonts={[]} position={[0, -50, 0]} fontSize={90} color="#ffffff" anchorX="center" anchorY="middle" letterSpacing={0.1}>
            AUTOPILOT
          </Text>
          <Text font="/fonts/Roboto.woff" fallbackFonts={[]} position={[0, -120, 0]} fontSize={30} color="#00aaff" anchorX="center" anchorY="middle" letterSpacing={0.2}>
            AUTONOMOUS BUSINESS AGENT
          </Text>
        </Float>
      </group>
    </group>
  );
};

export default WorldAutopilot;
