import React from 'react';
import { Helmet } from 'react-helmet';
import { useProgress } from '@react-three/drei';
import Header from '../../components/ui/Header';
import Scene3D from './components/Scene3D';
import VoiceAgentSystem from './components/VoiceAgentSystem';
import GenerativeHUD from './components/GenerativeHUD';

const CustomLoader = () => {
  const { active, progress } = useProgress();
  if (!active) return null;
  return (
    <div className="absolute top-0 left-0 w-full h-full flex items-center justify-center z-[100] pointer-events-none bg-[#0a0a1a]">
      <div className="flex flex-col items-center justify-center bg-[#050505]/90 p-8 rounded-2xl border border-cyan-500/30 shadow-[0_0_50px_rgba(0,255,255,0.1)] backdrop-blur-xl w-[350px]">
        <div className="w-12 h-12 border-4 border-cyan-500 border-t-transparent rounded-full animate-spin mb-6"></div>
        <div className="text-cyan-400 font-mono tracking-widest text-sm mb-2 text-center w-full">
          INITIALIZING WARP SEQUENCE
        </div>
        <div className="w-full bg-cyan-900/50 rounded-full h-1.5 overflow-hidden">
          <div className="bg-cyan-400 h-1.5 rounded-full transition-all duration-300" style={{ width: `${progress}%` }}></div>
        </div>
        <div className="text-cyan-500/70 font-mono text-xs mt-2">{progress.toFixed(0)}% LOADED</div>
      </div>
    </div>
  );
};

const Demo3DHome = () => {
  return (
    <div className="relative w-screen h-screen bg-gradient-to-b from-[#0a0a1a] to-[#020205] font-sans text-white overflow-hidden">
      <Helmet>
        <title>sentAIent | Quantum Wormhole Experience</title>
        <meta
          name="description"
          content="Explore our portfolio of autonomous marketing, legal analysis, wellness, and interactive entertainment platforms in a scroll-driven wormhole journey."
        />
        <meta name="theme-color" content="#0a0a1a" />
      </Helmet>
      
      <CustomLoader />

      {/* Header stays on top */}
      <div className="absolute top-0 left-0 w-full z-50">
        <Header />
      </div>

      {/* Full screen 3D Canvas */}
      <div className="absolute inset-0 z-0">
        <Scene3D />
      </div>

      {/* Voice Agent */}
      <div className="absolute bottom-10 left-1/2 transform -translate-x-1/2 z-50">
        <VoiceAgentSystem />
      </div>

      {/* Generative UI HUD Layer */}
      <GenerativeHUD />

    </div>
  );
};

export default Demo3DHome;
