import React, { useRef, useMemo } from 'react';
import { useFrame } from '@react-three/fiber';
import { Text, Float, useScroll, Image, MeshReflectorMaterial, Instance, Instances } from '@react-three/drei';
import * as THREE from 'three';
import AvatarSystem from '../components/AvatarSystem';

// --- VOLATILITY SINGULARITY ---
// Lorenz Attractor based particle vortex
const singularityVertexShader = `
  uniform float uTime;
  attribute float randomOffset;
  attribute vec3 colorAccent;
  attribute vec3 initialPos;
  varying vec3 vColor;

  void main() {
    vColor = colorAccent;
    
    vec3 pos = initialPos;
    
    // Animate points based on time and random offset
    // To simulate a strange attractor, we'll blend their initial position 
    // with a dynamic swirl that mimics the attractor's lobes.
    
    float t = uTime * 0.2 + randomOffset * 100.0;
    
    // Procedural fake-Lorenz motion for artistic effect
    float x = sin(t * 1.1) * cos(t * 0.8) * 400.0;
    float y = sin(t * 1.3) * sin(t * 0.5) * 400.0;
    float z = cos(t * 0.9) * 400.0;
    
    // Blend with initial spherical position
    pos.x = mix(pos.x, x, 0.6);
    pos.y = mix(pos.y, y, 0.6) + 200.0; // Shift up
    pos.z = mix(pos.z, z, 0.6);
    
    // Add rapid orbit
    float angle = uTime * 0.5 + randomOffset;
    float s = sin(angle);
    float c = cos(angle);
    float nx = pos.x * c - pos.z * s;
    float nz = pos.x * s + pos.z * c;
    
    vec3 finalPos = vec3(nx, pos.y, nz);
    
    vec4 mvPosition = modelViewMatrix * vec4(finalPos, 1.0);
    gl_PointSize = (150.0 / -mvPosition.z) * (1.0 + sin(uTime * 5.0 + randomOffset * 20.0) * 0.5);
    gl_Position = projectionMatrix * mvPosition;
  }
`;

const singularityFragmentShader = `
  varying vec3 vColor;
  void main() {
    float dist = length(gl_PointCoord - vec2(0.5));
    if (dist > 0.5) discard;
    float intensity = pow(1.0 - (dist * 2.0), 2.0);
    gl_FragColor = vec4(vColor * intensity * 2.0, intensity * 0.9);
  }
`;

const VolatilitySingularity = ({ position, visible }) => {
  const pointsRef = useRef();
  const particleCount = 40000; // Double the particles

  const [positions, initialPos, offsets, colors] = useMemo(() => {
    const pos = new Float32Array(particleCount * 3);
    const initP = new Float32Array(particleCount * 3);
    const offs = new Float32Array(particleCount);
    const cols = new Float32Array(particleCount * 3);
    
    const colorWhite = new THREE.Color('#ffffff');
    const colorGold = new THREE.Color('#ffaa00');
    const colorAmber = new THREE.Color('#ff5500');
    
    for (let i = 0; i < particleCount; i++) {
      const r = 300 + Math.random() * 200;
      const theta = Math.random() * Math.PI * 2;
      const phi = Math.acos((Math.random() * 2) - 1);
      
      const x = r * Math.sin(phi) * Math.cos(theta);
      const y = r * Math.sin(phi) * Math.sin(theta);
      const z = r * Math.cos(phi);
      
      pos[i * 3] = x; pos[i * 3 + 1] = y; pos[i * 3 + 2] = z;
      initP[i * 3] = x; initP[i * 3 + 1] = y; initP[i * 3 + 2] = z;
      
      offs[i] = Math.random();
      
      const randColor = Math.random();
      let c = randColor > 0.9 ? colorAmber : (randColor > 0.5 ? colorGold : colorWhite);
      cols[i * 3] = c.r; cols[i * 3 + 1] = c.g; cols[i * 3 + 2] = c.b;
    }
    return [pos, initP, offsets, cols];
  }, []);

  const uniforms = useMemo(() => ({ uTime: { value: 0 } }), []);
  useFrame((state) => {
    if (!visible) return;
    uniforms.uTime.value = state.clock.elapsedTime;
  });

  return (
    <group position={position}>
      <points ref={pointsRef}>
        <bufferGeometry>
          <bufferAttribute attach="attributes-position" count={particleCount} array={positions} itemSize={3} />
          <bufferAttribute attach="attributes-initialPos" count={particleCount} array={initialPos} itemSize={3} />
          <bufferAttribute attach="attributes-randomOffset" count={particleCount} array={offsets} itemSize={1} />
          <bufferAttribute attach="attributes-colorAccent" count={particleCount} array={colors} itemSize={3} />
        </bufferGeometry>
        <shaderMaterial
          vertexShader={singularityVertexShader}
          fragmentShader={singularityFragmentShader}
          uniforms={uniforms}
          transparent={true}
          depthWrite={false}
          blending={THREE.AdditiveBlending}
        />
      </points>
      <pointLight intensity={5} color="#ffaa00" distance={1500} />
    </group>
  );
};

// --- ORDER FLOW MONOLITHS ---
const monolithVertexShader = `
  varying vec2 vUv;
  varying vec3 vWorldPos;
  void main() {
    vUv = uv;
    vec4 worldPos = modelMatrix * instanceMatrix * vec4(position, 1.0);
    vWorldPos = worldPos.xyz;
    gl_Position = projectionMatrix * viewMatrix * worldPos;
  }
`;

const monolithFragmentShader = `
  varying vec2 vUv;
  varying vec3 vWorldPos;
  uniform float uTime;
  
  void main() {
    // Base obsidian color
    vec3 baseColor = vec3(0.01, 0.01, 0.015);
    
    // Data stream effect based on world Y position
    // Creates vertical bands of light flowing upwards
    float flow = fract(vWorldPos.y * 0.005 - uTime * 0.5);
    // Thin sharp lines
    float stream = step(0.95, flow) * step(flow, 0.98);
    
    // Add random horizontal variation using sine
    float variation = sin(vWorldPos.x * 0.1) * cos(vWorldPos.z * 0.1);
    stream *= smoothstep(0.0, 0.5, variation + 0.5);
    
    vec3 glowColor = vec3(1.0, 0.6, 0.0) * stream * 2.0;
    
    // Add a subtle grid/circuit pattern
    float grid = step(0.98, fract(vUv.x * 20.0)) + step(0.98, fract(vUv.y * 20.0));
    vec3 circuitColor = vec3(0.2, 0.1, 0.0) * grid * 0.5;
    
    vec3 finalColor = baseColor + glowColor + circuitColor;
    
    gl_FragColor = vec4(finalColor, 1.0);
  }
`;

const OrderFlowMonoliths = ({ visible }) => {
  const count = 60;
  const uniforms = useMemo(() => ({ uTime: { value: 0 } }), []);

  useFrame((state) => {
    if (!visible) return;
    uniforms.uTime.value = state.clock.elapsedTime;
  });

  const instances = useMemo(() => {
    const arr = [];
    for (let i = 0; i < count; i++) {
      const angle = (i / count) * Math.PI * 2;
      const r = 600 + (Math.random() * 300);
      const x = Math.cos(angle) * r;
      const z = Math.sin(angle) * r;
      const height = 400 + Math.random() * 600;
      arr.push({
        position: [x, height / 2 - 400, z],
        rotation: [0, -angle, 0],
        scale: [1, height, 1]
      });
    }
    return arr;
  }, [count]);

  return (
    <Instances range={count} material={new THREE.ShaderMaterial({
      vertexShader: monolithVertexShader,
      fragmentShader: monolithFragmentShader,
      uniforms: uniforms,
      side: THREE.DoubleSide
    })}>
      <boxGeometry args={[80, 1, 40]} />
      {instances.map((props, i) => (
        <Instance key={i} {...props} />
      ))}
    </Instances>
  );
};

// --- DARK POOL FLOOR ---
const DarkPool = () => {
  return (
    <group position={[0, -400, 0]}>
      <mesh rotation={[-Math.PI / 2, 0, 0]}>
        <planeGeometry args={[5000, 5000]} />
        <MeshReflectorMaterial
          blur={[1000, 500]}
          resolution={1024}
          mixBlur={1.0}
          mixStrength={100}
          roughness={0.02}
          depthScale={1.5}
          minDepthThreshold={0.4}
          maxDepthThreshold={1.4}
          color="#000000"
          metalness={1.0}
        />
      </mesh>
      
      {/* Subsurface Grid/Circuitry */}
      <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, -1, 0]}>
        <planeGeometry args={[5000, 5000, 50, 50]} />
        <meshBasicMaterial color="#ffaa00" wireframe transparent opacity={0.05} blending={THREE.AdditiveBlending} />
      </mesh>
    </group>
  );
};

// --- MAIN COMPONENT ---
const ContangoQuant = ({ position, rotation, visible }) => {
  const scroll = useScroll();
  const lockRef = useRef({ triggered: false, timer: 0, locked: false });

  useFrame((state, delta) => {
    if (!visible) return;
    const p = scroll.offset;
    const s = lockRef.current;
    
    if (!s.triggered && p >= 0.92) {
      s.triggered = true;
      s.locked = true;
      if (scroll.el) {
        scroll.el.style.overflow = 'hidden';
        scroll.el.scrollTop = 0.93 * (scroll.el.scrollHeight - scroll.el.clientHeight);
      }
    }
    
    if (s.locked) {
      s.timer += delta;
      if (s.timer > 2.0) {
        s.locked = false;
        if (scroll.el) scroll.el.style.overflow = 'auto';
      } else {
        if (scroll.el) scroll.el.scrollTop = 0.93 * (scroll.el.scrollHeight - scroll.el.clientHeight);
      }
    }
  });

  return (
    <group visible={visible} position={position} rotation={rotation}>
      <ambientLight intensity={0.1} color="#ffffff" />
      
      <mesh rotation={[0, -Math.PI / 2, 0]}>
        <sphereGeometry args={[4000, 32, 32]} />
        <meshBasicMaterial color="#010101" side={THREE.BackSide} />
      </mesh>

      <DarkPool />
      <OrderFlowMonoliths visible={visible} />
      <VolatilitySingularity position={[0, 0, -800]} visible={visible} />

      <Float speed={1.5} rotationIntensity={0.02} floatIntensity={0.2}>
        <Image url="/contango_quant_logo.png" position={[0, 350, -800]} scale={[300, 300]} transparent opacity={0.9} />
        <Text position={[0, 170, -800]} fontSize={100} font="/fonts/Roboto.woff" fallbackFonts={[]} color="#ffffff" letterSpacing={0.1}>
          CONTANGO QUANT
        </Text>
        <Text position={[0, 80, -800]} fontSize={35} font="/fonts/Roboto.woff" fallbackFonts={[]} color="#ffaa00" letterSpacing={0.2}>
          THE PHYSICS OF FINANCE
        </Text>
      </Float>

      {visible && <AvatarSystem position={[0, -200, -400]} scale={2.0} greeting="Initializing Contango Quant. Order flow singularity stable." />}
    </group>
  );
};

export default ContangoQuant;
